# Signal mssgbox
class at_signal_mssgbox(QObject):
    at_signal = pyqtSignal(str)
    
    def __init__(self):
        super().__init__()
        self.at_signal.connect(self.at_check_signal)
        
    def at_check_signal(self,msg):
        if msg == "None_target_url":
            QMessageBox.warning(None, 'Error Message Box', 'Please input the URL and parameter!', QMessageBox.Close)
        elif msg == "None_header":
            QMessageBox.warning(None, 'Error Message Box', 'Please input the Cookie!', QMessageBox.Close)
        elif msg == "DOM":
            QMessageBox.information(None, 'Information Message Box', 'XSStrike DOM vulnerabilities Found!\n Please check attack tools Raw Result', QMessageBox.Close)
            pass
        pass
    pass

