            self.chk_sqlmap_db_name.show()
            self.cmb_sqlmap_db_name.show()
            self.chk_sqlmap_table_name.show()
            self.cmb_sqlmap_table_name.show()
            # self.btn_get_header_file.show()
            # self.btn_using_header_file.show()
