            self.btn_using_header_file.setChecked(False)
            self.btn_sqlmap_records_arg.show()
            self.lbl_sqlmap_level.show()
            self.cmb_sqlmap_level.show()
            self.lbl_sqlmap_risk.show()
            self.cmb_sqlmap_risk.show()
            self.chk_sqlmap_header.show()
            self.txt_sqlmap_header.show()
            self.chk_xsstrike_header.hide()
            self.txt_xsstrike_header.hide()
            self.chk_xsstrike_fuzzer.hide()
            self.chk_xsstrike_skip_dom.hide()
