    def make_scanning_thread(self):
        self.at_call_signal = at_signal_mssgbox()
        scan_thread = threading.Thread(target=self.thread_scan)
        scan_thread.start()
        pass

    def thread_scan(self):
        result_raw = ""
        
        # SQLMap Scan
        if self.cmb_tool.currentText() == "SQLmap":
            # Get value
            tables_arg = self.chk_sqlmap_tables_arg.isChecked()
            columns_arg = self.btn_sqlmap_columns_arg.isChecked()
            records_arg = self.btn_sqlmap_records_arg.isChecked()
            db_name = self.cmb_sqlmap_db_name.currentText()
            table_name = self.cmb_sqlmap_table_name.currentText()
            level_arg = self.cmb_sqlmap_level.currentText()
            risk_arg = self.cmb_sqlmap_risk.currentText()
            
            if self.chk_sqlmap_header.isChecked() == False:
                phpSessId = None
            elif self.chk_sqlmap_header.isChecked() == True:
                phpSessId = self.txt_sqlmap_header.text()
                if phpSessId == "":
                    self.at_call_signal.at_signal.emit("None_header")
                    time.sleep(1)
                    return False
            
            self.btn_result_record_to_db.setDisabled(True)
            self.table_namp.clear()

            if self.btn_using_user_url.isChecked() == True:
                injection_point = str(self.txt_target_url.text())
                if injection_point == "":
                    self.at_call_signal.at_signal.emit("None_target_url")
                    time.sleep(1)
                    return False
                
                self.btn_scan.setDisabled(True)
                self.btn_exit.setDisabled(True)
                self.at_pb.show()
                self.lbl_tool_name.hide()
                
                # Call SQLMap API
                if (self.chk_sqlmap_db_name.isChecked() == True) and (self.chk_sqlmap_table_name.isChecked() == True):
                    self.sqlmap_scan = SQLMap(injection_point=injection_point,user_agent="FYP",tables_arg=tables_arg,columns_arg=columns_arg,records_arg=records_arg, level_arg=level_arg, risk_arg=risk_arg, db_name=db_name,table_name=table_name,phpSessId=phpSessId)
                    pass
                elif self.chk_sqlmap_db_name.isChecked() == True:
                    self.sqlmap_scan = SQLMap(injection_point=injection_point,user_agent="FYP",tables_arg=tables_arg,level_arg=level_arg, risk_arg=risk_arg,db_name=db_name,phpSessId=phpSessId)
                else:
                    self.sqlmap_scan = SQLMap(injection_point=injection_point,user_agent="FYP",level_arg=level_arg, risk_arg=risk_arg,phpSessId=phpSessId)
                pass
            # Use Header File 
            # elif self.btn_using_header_file.isChecked() == True:
            #     try:
            #         if self.header_txt_file == "":
            #             QMessageBox.critical(
            #                                 self,
            #                                 'Sorry',
            #                                 'Please select the header txt file!'
            #                         )
            #             return False
            #         injection_point = self.header_txt_file
            #     except:
            #         QMessageBox.critical(
            #                             self,
            #                             'Sorry',
            #                             'Please select the header txt file!'
            #                         )
            #         return False
            #         pass
            #     if (self.chk_sqlmap_db_name.isChecked() == True) and (self.chk_sqlmap_table_name.isChecked() == True):
            #         self.sqlmap_scan = SQLMap(injection_point=injection_point,user_agent="FYP",tables_arg=tables_arg,columns_arg=columns_arg,records_arg=records_arg,level_arg=level_arg, risk_arg=risk_arg,db_name=db_name,table_name=table_name,phpSessId=phpSessId)
            #         pass
            #     elif self.chk_sqlmap_db_name.isChecked() == True:
            #         self.sqlmap_scan = SQLMap(injection_point=injection_point,user_agent="FYP",tables_arg=tables_arg,level_arg=level_arg, risk_arg=risk_arg,db_name=db_name,phpSessId=phpSessId)
            #     else:
            #         self.sqlmap_scan = SQLMap(injection_point=injection_point,user_agent="FYP",level_arg=level_arg, risk_arg=risk_arg,phpSessId=phpSessId)
            #     pass

            #     # self.btn_get_header_file.clicked.connect(self.select_header_txt_file())
                
            #     pass
            # else:
            #     pass
            
            # Start the SQLMap Scan
            self.sqlmap_scan_result = self.sqlmap_scan.sqlmap_get_methon()
            self.sqlmap_scan_filter_result = self.sqlmap_scan.sqlmap_result_filter()

            #Display Raw Result
            for loop in self.sqlmap_scan_result:
                    result_raw += f"{loop}"
                    self.lbl_raw_result.setText(result_raw)
                    self.lbl_raw_result.adjustSize()
                    pass
                
            self.chk_sqlmap_db_name.setDisabled(False)
            self.chk_sqlmap_table_name.setDisabled(False)
            # self.lbl_tool_name.setText("Config:")

            # sqlmap result list arg
            sqlmap_result_arg_temp_dbs_array = 0
            sqlmap_result_arg_temp_dict = 1
            sqlmap_result_arg_tables_temp_array= 2
            sqlmap_result_arg_columns_temp_dict = 3
            sqlmap_result_arg_records_temp_array = 4

            # display database list to combobox
            if len(self.sqlmap_scan_filter_result[sqlmap_result_arg_temp_dbs_array]) != 0:
                self.cmb_sqlmap_db_name.clear()
                self.cmb_sqlmap_db_name.addItems(self.sqlmap_scan_filter_result[sqlmap_result_arg_temp_dbs_array])
                self.btn_result_record_to_db.setDisabled(False)
                
            # display database table list to combobox
            if len(self.sqlmap_scan_filter_result[sqlmap_result_arg_tables_temp_array]) != 0 :  
                self.cmb_sqlmap_table_name.clear()
                self.cmb_sqlmap_table_name.addItems(self.sqlmap_scan_filter_result[sqlmap_result_arg_tables_temp_array])
                self.btn_result_record_to_db.setDisabled(False)

            # diplay sqlmap result to result tab table
            result = ""
            for i in self.sqlmap_scan_filter_result:
                result += f"{i}\n"
                # self.lbl_tool.setText(result)
                print(i)
            if self.chk_sqlmap_table_name.isChecked():
                # diplay sqlmap selected table column information
                if self.btn_sqlmap_columns_arg.isChecked() :

                    temp_list = self.sqlmap_scan_filter_result[sqlmap_result_arg_columns_temp_dict]
                    if len(temp_list) != 0:
                        self.table_namp.setRowCount(len(temp_list))
                        self.table_namp.setColumnCount(2)

                        self.table_namp.setHorizontalHeaderLabels(['Column','DataType'])
                        line = 0
                        for key in temp_list:
                            self.table_namp.setItem(line,0 ,QTableWidgetItem(key) )
                            self.table_namp.setItem(line,1, QTableWidgetItem(temp_list[key]) )
                            line = line + 1
                # diplay sqlmap result selected table record
                elif self.btn_sqlmap_records_arg.isChecked() :
                    temp_list = self.sqlmap_scan_filter_result[sqlmap_result_arg_records_temp_array]
                    if len(temp_list)!=0:
                        self.table_namp.setRowCount(len(temp_list))
                        self.table_namp.setColumnCount(len(temp_list[0]))
                        self.table_namp.setHorizontalHeaderLabels(temp_list[0])
                        record_count = 0
                        for record in temp_list:
                            key_count = 0
                            for key in record:
                                self.table_namp.setItem(record_count,key_count,QTableWidgetItem(record[key]))
                                key_count = key_count + 1
                            record_count = record_count + 1
                    pass

        # XSStrike Scan
        elif self.cmb_tool.currentText() == "XSStrike":
            # Get value
            if self.btn_using_user_url.isChecked() == True:
                target = str(self.txt_target_url.text())
                if target == "":
                    self.at_call_signal.at_signal.emit("None_target_url")
                    time.sleep(1)
                    return False
                
                if self.chk_xsstrike_header.isChecked() == True:
                    headers = str(self.txt_xsstrike_header.text()) 
                    if headers == "":
                        self.at_call_signal.at_signal.emit("None_header")
                        time.sleep(1)
                        return False
                    
                skip_dom = self.chk_xsstrike_skip_dom.isChecked()
                fuzzer_mode = self.chk_xsstrike_fuzzer.isChecked()
                
                self.btn_scan.setDisabled(True)
                self.btn_exit.setDisabled(True)
                self.at_pb.show()
                self.lbl_tool_name.hide()
                
                # Call XSStrike API
                self.xsstrike_scan = XSStrike(target=target, headers=headers, skip_dom=skip_dom, fuzzer_mode=fuzzer_mode, xsstrike_filter_arg=True)
                
                # Start XSStrike Scan
                self.xsstrike_scan_raw_result, self.xsstrike_scan_result_filtered = self.xsstrike_scan.xsstrike_scan()
                print(self.xsstrike_scan_result_filtered)
                
                #Display Raw Result
                for loop in self.xsstrike_scan_raw_result:
                    result_raw += f"{loop}"
                    self.lbl_raw_result.setText(result_raw)
                self.lbl_raw_result.adjustSize()
                
                #Display table result
                if type(self.xsstrike_scan_result_filtered) == list :#fuzzer
                    self.btn_result_record_to_db.setDisabled(False)
                    # print(f"filtered: {self.xsstrike_scan_result_filtered}")
                    self.table_namp.setRowCount(len(self.xsstrike_scan_result_filtered))
                    self.table_namp.setColumnCount(1)
                    self.table_namp.setHorizontalHeaderLabels(['possible payload'])
                    row = 0
                    for data in self.xsstrike_scan_result_filtered:
                        self.table_namp.setItem(row,0,QTableWidgetItem(data))
                        row = row + 1
                    self.table_namp.setColumnWidth(0,800)

                elif type(self.xsstrike_scan_result_filtered) == dict:# Payload/ DOM and Paylosd
                    if self.xsstrike_scan_result_filtered["DOM"] == True:
                        self.at_call_signal.at_signal.emit("DOM")
                        pass
                    if self.xsstrike_scan_result_filtered["Payload"] != "May not provide payload": #return database
                        
                        pass
                    pass
        else:
            pass
        
        self.lbl_raw_result.adjustSize()
        self.at_raw_topFiller.adjustSize()
        self.btn_scan.setDisabled(False)
        self.btn_exit.setDisabled(False)
        self.lbl_tool_name.show()
        self.at_pb.hide()
        pass

        

