    def select_header_txt_file(self):
        dialog = QFileDialog()
        dialog.setFileMode(QFileDialog.AnyFile)
        dialog.setFilter(QDir.Files)
        dialog.setNameFilter("*.txt")

        if dialog.exec_():
            self.header_txt_file  = dialog.selectedFiles()
            if type(self.header_txt_file) == list and len(self.header_txt_file) == 1:
                if self.header_txt_file[0].endswith(".txt"):
                    self.header_txt_file = self.header_txt_file[0]
                    return True 
                else:
                    QMessageBox.critical(
                                        self,
                                        'Error',
                                        'only allow import one txt file!'
                                    )
                    return False          
        else:
            return False
        
